import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`anyone on the team: see the full pipeline at a glance with leads grouped by stage and value totals per stage`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`the pipeline view always shows every active lead grouped under its current stage with a summed deal value per stage, refreshing live as leads are moved or added`, async ({ page }) => {
    // The pipeline board must already be visible (loginViaHash lands here)
    await expect(page.getByRole('heading', { name: 'Pipeline' })).toBeVisible({ timeout: 5_000 });

    // Add a lead with a known value so we can verify the per-stage value total
    await page.getByRole('button', { name: '+ Add Lead' }).click();
    await expect(page.getByText('Add Lead')).toBeVisible({ timeout: 5_000 });
    await page.getByLabel('Lead / Contact Name').fill('E2E Pipeline View Lead');
    await page.getByLabel('Company').fill('View Corp');
    // $25 000 → formatValue renders as "$25K"
    await page.getByLabel('Estimated Deal Value ($)').fill('25000');
    await page.getByRole('button', { name: 'Add Lead' }).click();

    // Lead card appears under its current stage column
    await expect(page.getByText('E2E Pipeline View Lead')).toBeVisible({ timeout: 10_000 });

    // The stage column now shows a summed deal value of $25K
    await expect(page.getByText('$25K')).toBeVisible({ timeout: 10_000 });
  });
});
